public final class Money {
    private static final Map<String, Money> ZERO = new ConcurrentHashMap<>();
    public static Money of(String currency, BigDecimal amount) {   // validated route
        return new Money(currency, amount.setScale(2, RoundingMode.HALF_UP));
    }
    public static Money zero(String currency) {                     // cached route
        return ZERO.computeIfAbsent(currency, c -> new Money(c, BigDecimal.ZERO));
    }
    private Money(String currency, BigDecimal amount) { ... }
}
